// AgriDOST 4.0 - Weather Data Processor
// Standardizes input and enforces agronomic baseline thresholds
const item = $input.first();
const payload = (item.json.body && item.json.body.payload) ? item.json.body.payload : (item.json.payload || item.json);

// Safe Agronomic Fallback Defaults
const defaultWeather = {
  temperatureC: 24,
  windSpeedKmh: 8,
  humidityPct: 60,
  precipitationProbPct: 5,
  condition: 'Clear - Fallback',
  forecastTimestamp: new Date().toISOString(),
  provider: 'agridost-weather-engine'
};

const defaultThresholds = {
  maxWindSpeedKmh: 15, // CIBRC / DGCA Spray threshold: max 15 km/h
  maxTempC: 35,        // Avoid thermal drift & foliar burn: max 35°C
  minHumidityPct: 40   // Avoid premature evaporation: min 40%
};

const weatherData = Object.assign({}, defaultWeather, payload.weatherData || {});
const thresholds = Object.assign({}, defaultThresholds, payload.thresholds || {});

const farmId = (item.json.body && item.json.body.farmId) || item.json.farmId || 'demo-farm-01';
const farmerId = (item.json.body && item.json.body.farmerId) || item.json.farmerId || 'demo-farmer-01';
const eventId = (item.json.body && item.json.body.eventId) || item.json.eventId || ('evt_' + Math.random().toString(36).slice(2));
const eventType = (item.json.body && item.json.body.eventType) || item.json.eventType || 'operations.spray.window_evaluation';
const operationType = payload.operationType || 'spray';

return [{
  json: {
    eventId,
    eventType,
    farmId,
    farmerId,
    operationType,
    zoneId: payload.zoneId || 'all',
    zoneName: payload.zoneName || (payload.zoneId ? `Zone ${payload.zoneId}` : 'All Parcels'),
    targetCrop: payload.targetCrop || 'General Crop',
    chemicalName: payload.chemicalName || null,
    dosagePerAcre: payload.dosagePerAcre || null,
    scheduledTime: payload.scheduledTime || new Date().toISOString(),
    weatherData,
    thresholds,
    rawInput: payload
  }
}];

// AgriDOST 4.0 - Spray & Irrigation Feasibility Evaluator
// Evaluates optimal/caution/unsafe suitability & enforces mandatory advisory-only safety gate
const item = $input.first().json;
const weather = item.weatherData;
const thresholds = item.thresholds;

const violations = [];
const warnings = [];

// 1. Wind Speed Evaluation (Max 15 km/h for spraying)
if (weather.windSpeedKmh > thresholds.maxWindSpeedKmh) {
  violations.push(`Wind speed (${weather.windSpeedKmh} km/h) exceeds safe threshold (${thresholds.maxWindSpeedKmh} km/h). Severe chemical drift hazard.`);
} else if (weather.windSpeedKmh >= 12) {
  warnings.push(`Wind speed (${weather.windSpeedKmh} km/h) is near upper safety margin (15 km/h). Lower flight altitude advised.`);
} else if (weather.windSpeedKmh < 3) {
  warnings.push(`Low wind speed (${weather.windSpeedKmh} km/h). Risk of microclimate inversion.`);
}

// 2. Precipitation Probability Evaluation (Max 30%)
if (weather.precipitationProbPct > 30) {
  violations.push(`Precipitation probability (${weather.precipitationProbPct}%) exceeds safe limit (30%). Rain wash-off risk.`);
} else if (weather.precipitationProbPct >= 20) {
  warnings.push(`Moderate rain probability (${weather.precipitationProbPct}%). Allow 2-4 hours rain-fast window.`);
}

// 3. Temperature Evaluation (Max 35°C)
if (weather.temperatureC > thresholds.maxTempC) {
  violations.push(`Temperature (${weather.temperatureC}°C) exceeds safe threshold (${thresholds.maxTempC}°C). Evaporation and phytotoxicity risk.`);
} else if (weather.temperatureC >= 30) {
  warnings.push(`Elevated temperature (${weather.temperatureC}°C). Morning application recommended.`);
}

// 4. Humidity Evaluation
if (weather.humidityPct < thresholds.minHumidityPct) {
  warnings.push(`Low humidity (${weather.humidityPct}%). Droplets may evaporate rapidly.`);
}

// Determine Overall Suitability
let suitability = 'optimal';
if (violations.length > 0) {
  suitability = 'unsafe';
} else if (warnings.length > 0) {
  suitability = 'caution';
}

// Irrigation Specific Evaluation
let irrigationAdvisory = null;
if (weather.precipitationProbPct >= 40) {
  irrigationAdvisory = {
    action: 'postpone',
    recommendedVolumePct: 0,
    reason: `Heavy rain chance (${weather.precipitationProbPct}%). Postpone irrigation to save water and avoid waterlogging.`
  };
} else if (weather.temperatureC > 32 && weather.humidityPct < 50) {
  irrigationAdvisory = {
    action: 'schedule_early_morning_or_evening',
    recommendedVolumePct: 100,
    reason: 'High evapotranspiration. Water strictly in early morning or late evening.'
  };
} else {
  irrigationAdvisory = {
    action: 'proceed',
    recommendedVolumePct: 100,
    reason: 'Optimal atmospheric moisture conditions.'
  };
}

// MANDATORY SAFETY GATE: Autonomous drone spray / flight execution strictly blocked
const safetyGate = {
  autonomousExecutionBlocked: true,
  autonomousExecutionAllowed: false,
  advisoryOnly: true,
  requiresFarmerConfirmation: true,
  status: 'advisory_only',
  complianceNotice: 'In accordance with CIBRC & DGCA agricultural aviation norms, autonomous chemical spraying is blocked. Farmer validation is mandatory.'
};

return [{
  json: {
    ...item,
    suitability,
    violations,
    warnings,
    irrigationAdvisory,
    safetyGate,
    evaluationTimestamp: new Date().toISOString()
  }
}];

// AgriDOST 4.0 - Notification Builder
// Constructs localized bilingual alerts (English & Hindi) for the farmer and signs HMAC callback
const crypto = require('crypto');
const item = $input.first().json;
const suitability = item.suitability;
const zone = item.zoneName;
const weather = item.weatherData;
const isSpray = item.operationType === 'spray';
const secret = $env.N8N_WEBHOOK_SECRET || 'agridost_hmac_webhook_signing_secret_2026';
const baseAppUrl = ($env.AGRIDOST_APP_URL || $env.NEXT_PUBLIC_APP_URL || 'http://host.docker.internal:3000').replace(/\/$/, '');

let alertEn = {};
let alertHi = {};

if (suitability === 'unsafe') {
  alertEn = {
    title: `🚨 Spray Advisory: UNSAFE Weather Conditions`,
    summary: `Operations in ${zone} are UNSAFE. Wind: ${weather.windSpeedKmh} km/h, Rain: ${weather.precipitationProbPct}%, Temp: ${weather.temperatureC}°C.`,
    actionRecommendation: `DO NOT SPRAY. Postpone drone flight until wind drops below 12 km/h and rain probability subsides.`
  };
  alertHi = {
    title: `🚨 छिड़काव सलाह: मौसम असुरक्षित है`,
    summary: `${zone} में छिड़काव असुरक्षित है। हवा: ${weather.windSpeedKmh} किमी/घंटा, बारिश: ${weather.precipitationProbPct}%, तापमान: ${weather.temperatureC}°C।`,
    actionRecommendation: `छिड़काव न करें। हवा की गति 12 किमी/घंटा से नीचे आने और बारिश की संभावना कम होने तक ड्रोन संचालन स्थगित करें।`
  };
} else if (suitability === 'caution') {
  alertEn = {
    title: `⚠️ Spray Advisory: CAUTION Advised`,
    summary: `Marginal conditions in ${zone}. Wind: ${weather.windSpeedKmh} km/h, Temp: ${weather.temperatureC}°C.`,
    actionRecommendation: `Proceed with caution. Monitor drift closely and use anti-drift spray nozzles.`
  };
  alertHi = {
    title: `⚠️ छिड़काव सलाह: सावधानी बरतें`,
    summary: `${zone} में मौसमी परिस्थितियां सीमांत हैं। हवा: ${weather.windSpeedKmh} किमी/घंटा, तापमान: ${weather.temperatureC}°C।`,
    actionRecommendation: `सावधानी से कार्य करें। बहाव पर कड़ी नजर रखें और एंटी-ड्रिफ्ट नोजल का उपयोग करें।`
  };
} else {
  alertEn = {
    title: `✅ Spray Advisory: OPTIMAL Weather Window`,
    summary: `Weather conditions in ${zone} are OPTIMAL for spraying. Wind: ${weather.windSpeedKmh} km/h, Temp: ${weather.temperatureC}°C.`,
    actionRecommendation: `Safe to proceed with planned application. Verify flight perimeter and safety checks.`
  };
  alertHi = {
    title: `✅ छिड़काव सलाह: अनुकूल मौसम`,
    summary: `${zone} में छिड़काव के लिए मौसम पूरी तरह अनुकूल है। हवा: ${weather.windSpeedKmh} किमी/घंटा, तापमान: ${weather.temperatureC}°C।`,
    actionRecommendation: `योजना के अनुसार संचालन शुरू करना सुरक्षित है। सुरक्षा जांच पूरी करें।`
  };
}

const timestamp = new Date().toISOString();
const callbackPayload = {
  eventId: item.eventId,
  workflowId: 'smart-farm-operations',
  status: 'success',
  inputSummary: `${item.operationType.toUpperCase()} feasibility check on farm ${item.farmId} (${item.zoneName})`,
  outputSummary: `Feasibility: ${suitability.toUpperCase()} (Wind: ${weather.windSpeedKmh} km/h, Rain: ${weather.precipitationProbPct}%)`,
  outputData: {
    suitability,
    violations: item.violations,
    warnings: item.warnings,
    bilingualAlert: { en: alertEn, hi: alertHi },
    irrigationAdvisory: item.irrigationAdvisory,
    safetyGate: item.safetyGate,
    weatherData: item.weatherData,
    thresholds: item.thresholds
  },
  completedAt: timestamp
};

const rawBody = JSON.stringify(callbackPayload);
const signature = crypto
  .createHmac('sha256', secret)
  .update(`${timestamp}.${rawBody}`)
  .digest('hex');

const signatureHeader = `t=${timestamp},v1=${signature}`;
const callbackUrl = `${baseAppUrl}/api/n8n/callback`;

return [{
  json: {
    ...item,
    bilingualAlert: {
      en: alertEn,
      hi: alertHi
    },
    callbackPayload,
    callbackUrl,
    rawBody,
    signatureHeader,
    sigTimestamp: timestamp
  }
}];
